document.addEventListener("DOMContentLoaded",()=>{const button=document.querySelector(".menu-button"),nav=document.getElementById("site-navigation");if(!button||!nav)return;button.addEventListener("click",()=>{const opened=nav.classList.toggle("open");button.setAttribute("aria-expanded",String(opened));});nav.querySelectorAll("a").forEach(link=>link.addEventListener("click",()=>{nav.classList.remove("open");button.setAttribute("aria-expanded","false");}));});